-- =========================================================================
--  29 · Planchas de cartografía social como fondo del mapa
--
--   a) plancha: una por predio, con sus límites en grados (EPSG:4326) para
--      ponerla en el mapa, la etiqueta impresa (CBA 10, CPA 30…) y su estado
--      (ok · nubes · regenerar). El técnico ve las planchas de sus predios.
--   b) Bucket privado «planchas»: archivos <cod_predio>.jpg. Ve la imagen
--      quien ve el predio; solo el administrador sube o reemplaza.
--   c) Carga de los límites de las 240 planchas de Caquetá (georreferenciadas
--      con la cuadrícula de 250 m de cada plancha, error < 1,5 m).
-- =========================================================================

-- a) ------------------------------------------------------------------------------------
create table productores.plancha (
  predio_id   uuid primary key references productores.predio (id) on delete cascade,
  etiqueta    text not null,
  sur         double precision not null,
  oeste       double precision not null,
  norte       double precision not null,
  este        double precision not null,
  estado      text not null default 'ok' check (estado in ('ok', 'nubes', 'regenerar')),
  nota        text,
  subida_en   timestamptz,
  creado_en   timestamptz not null default now(),
  check (norte > sur and este > oeste)
);
alter table productores.plancha enable row level security;
create policy plancha_ver on productores.plancha for select to authenticated
  using (productores.ve_predio(predio_id));
create policy plancha_admin on productores.plancha for all to authenticated
  using (productores.es_admin()) with check (productores.es_admin());
revoke all on productores.plancha from public, anon;
grant select, insert, update, delete on productores.plancha to authenticated;
grant select on productores.plancha to sig_editor;

-- b) ------------------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('planchas', 'planchas', false, 5242880, array['image/jpeg'])
on conflict (id) do nothing;

create or replace function productores.ve_ruta_plancha(p_nombre text)
returns boolean language sql stable security definer set search_path to ''
as $$
  select exists (select 1 from productores.predio p
                  where p.cod_predio = regexp_replace(p_nombre, '\.jpg$', '')
                    and productores.ve_predio(p.id))
$$;
revoke execute on function productores.ve_ruta_plancha(text) from public, anon;
grant execute on function productores.ve_ruta_plancha(text) to authenticated;

create policy planchas_ver on storage.objects for select to authenticated
  using (bucket_id = 'planchas' and productores.ve_ruta_plancha(name));
create policy planchas_subir on storage.objects for insert to authenticated
  with check (bucket_id = 'planchas' and productores.es_admin());
create policy planchas_reemplazar on storage.objects for update to authenticated
  using (bucket_id = 'planchas' and productores.es_admin())
  with check (bucket_id = 'planchas' and productores.es_admin());
create policy planchas_borrar on storage.objects for delete to authenticated
  using (bucket_id = 'planchas' and productores.es_admin());

-- c) ------------------------------------------------------------------------------------
